function elbowPath(x1, y1, x2, y2, r) {
  if (Math.abs(x2 - x1) < 0.5) return `M ${x1} ${y1} L ${x2} ${y2}`;
  const midY = y1 + (y2 - y1) / 2;
  const dir = x2 > x1 ? 1 : -1;
  const rr = Math.min(r, Math.abs(x2 - x1) / 2, Math.abs(midY - y1), Math.abs(y2 - midY));
  return `M ${x1} ${y1} L ${x1} ${midY - rr} Q ${x1} ${midY} ${x1 + dir * rr} ${midY} L ${x2 - dir * rr} ${midY} Q ${x2} ${midY} ${x2} ${midY + rr} L ${x2} ${y2}`;
}

function FunnelPageDetail({ page, open, onToggle }) {
  const bps = [["desktop", "Desktop"], ["tablet", "Tablet"], ["mobile", "Mobile"]];
  return (
    <div className={`fpage-card ${open ? "is-open" : ""}`}>
      <button className="fpage-head" onClick={onToggle}>
        <span className="fpage-num">{String(page.num).padStart(2, "0")}</span>
        <span className="fpage-headtext">
          <b>{page.title}</b>
          <span>{page.purpose}</span>
        </span>
        <ChevronDown className={`persona-chev ${open ? "rot" : ""}`} size={20} />
      </button>
      {open && (
        <div className="fpage-body">
          <div className="fpage-block-label">Sections on this page</div>
          <ul className="fpage-sections">
            {page.sections.map((s) => <li key={s}>{s}</li>)}
          </ul>
          <div className="fpage-row">
            <div>
              <div className="fpage-block-label">Responsive</div>
              <div className="fpage-bps">
                {bps.map(([key, label]) => (
                  <span key={key} className={`fpage-bp ${page.responsive[key] ? "yes" : "no"}`}>{label}</span>
                ))}
              </div>
            </div>
          </div>
          <div className="fpage-block-label">Old → New</div>
          <p className="fpage-oldnew">{page.oldNew}</p>
        </div>
      )}
    </div>
  );
}

function SiteMapTree({ data }) {
  const n = data.branches.length;
  const branchX = (i) => ((i + 0.5) / n) * 100;
  return (
    <div className="sitemap-tree">
      <div className="sitemap-root">{data.root}</div>
      <div className="sitemap-canvas">
        <svg className="sitemap-lines" viewBox="0 0 100 100" preserveAspectRatio="none">
          {data.branches.map((b, i) => (
            <path key={b.name} d={elbowPath(50, 0, branchX(i), 100, 18)} vectorEffect="non-scaling-stroke" />
          ))}
        </svg>
        <div className="sitemap-columns">
          {data.branches.map((b) => (
            <div className="sitemap-col" key={b.name}>
              <div className="sitemap-branch">{b.name}</div>
              <div className="sitemap-col-line" />
              <div className="sitemap-children">
                {b.items.map((it) => <div className="sitemap-item" key={it}>{it}</div>)}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function BreakpointRow({ title, items }) {
  return (
    <div className="cmp-block">
      <h3>{title}</h3>
      <div className="bp-row">
        {items.map((it) => (
          <div className="bp-item" key={it.label} style={{ flex: `${it.aspect} 1 0` }}>
            <img src={it.src} alt={`${title} — ${it.label}`} />
            <span className="bp-item-label">{it.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function FunnelWalkthrough({ steps }) {
  const [active, setActive] = useState(0);
  const step = steps[active];
  const items = [
    { label: "Desktop · 1440px", src: step.desktop.src, aspect: step.desktop.aspect },
    { label: "Tablet · 768px", src: step.tablet.src, aspect: step.tablet.aspect },
    { label: "Mobile · ~390px", src: step.mobile.src, aspect: step.mobile.aspect },
  ];
  return (
    <div className="cmp-block">
      <div className="funnel-tabs">
        {steps.map((s, i) => (
          <button key={s.num} className={i === active ? "active" : ""} onClick={() => setActive(i)}>
            <span className="mono">Step {s.num}/5</span>
            <b>{s.title}</b>
          </button>
        ))}
      </div>
      <div className="bp-row funnel-fade" key={active}>
        {items.map((it) => (
          <div className="bp-item" key={it.label} style={{ flex: `${it.aspect} 1 0` }}>
            <img src={it.src} alt={`${step.title} — ${it.label}`} />
            <span className="bp-item-label">{it.label}</span>
          </div>
        ))}
      </div>
      <p className="cmp-caption">Step {step.num} of 5 — "{step.title}".</p>
    </div>
  );
}


function PersonaCard({ p, open, onToggle }) {
  return (
    <div className={`persona-card ${open ? "is-open" : ""}`}>
      <button className="persona-head" onClick={onToggle}>
        <div className="persona-avatar" aria-hidden="true">
          {p.name.split(" ").map((n) => n[0]).join("")}
        </div>
        <div className="persona-headtext">
          <span className="persona-badge">{p.badge}</span>
          <h3>{p.name}</h3>
          <p>{p.role}</p>
        </div>
        <ChevronDown className={`persona-chev ${open ? "rot" : ""}`} size={20} />
      </button>

      <div className="persona-stats">
        <div><span className="mono">{p.age}</span><label>Age</label></div>
        <div><span className="mono">{p.location}</span><label>Location</label></div>
        <div><span className="mono">{p.stat3.value}</span><label>{p.stat3.label === "TENURE" ? "Tenure" : "Work"}</label></div>
      </div>

      {open && (
        <div className="persona-body">
          <div className="persona-cols">
            <div>
              <h4>Background</h4>
              <p>{p.background}</p>
            </div>
            <div>
              <h4>Current situation</h4>
              <p>{p.situation}</p>
            </div>
          </div>

          <h4>Core goals</h4>
          <ul className="persona-goals">
            {p.goals.map((g) => (
              <li key={g.title}>
                <strong>{g.title}</strong>
                <span>{g.desc}</span>
              </li>
            ))}
          </ul>

          <h4>Behavioral spectrum</h4>
          <div className="persona-traits">
            {p.traits.map((t) => (
              <div className="trait" key={t.label}>
                <div className="trait-label">
                  <span>{t.label}</span>
                  <span className="mono">{t.value}</span>
                </div>
                <div className="trait-track"><div className="trait-fill" style={{ width: `${t.pct}%` }} /></div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const ENERGY_EXTRA = ``;

